INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@wbcs_exam, 40, 'Arithmetic', 'Time & Work', 'Medium', 'A and B together can complete a task in 10 days. A alone can complete it in 15 days. In how many days can B alone complete the task?', 0, NULL, 'Combined rate = 1/10. A''s rate = 1/15. B''s rate = 1/10 − 1/15 = (3−2)/30 = 1/30, so B alone takes 30 days.', 'C');
